import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"自动发版","description":"CI Token 调用 ci/releases。任务进度走管理 jobs。","frontmatter":{"title":"自动发版","description":"CI Token 调用 ci/releases。任务进度走管理 jobs。"},"headers":[],"relativePath":"api/ci.md","filePath":"api/ci.md","lastUpdated":1790057721000}`),a={name:`api/ci.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="自动发版" tabindex="-1">自动发版 <a class="header-anchor" href="#自动发版" aria-label="Permalink to “自动发版”">​</a></h1><p>使用项目 <strong>CI Token</strong> 调用管理平面（默认 <code>:8081</code>）：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th></tr></thead><tbody><tr><td>GET, POST</td><td><code>/api/v1/admin/projects/{project_ref}/ci-tokens</code></td></tr><tr><td>DELETE</td><td><code>/api/v1/admin/projects/{project_ref}/ci-tokens/{token_id}</code></td></tr><tr><td>POST</td><td><code>/api/v1/admin/projects/{project_ref}/ci/releases</code></td></tr></tbody></table><p>GitHub Actions（或任何 CI/CD 平台）：把 CI Token 放进密钥，构建产物后 <code>POST ci/releases</code>。任务进度<strong>不</strong>在本页：<code>GET /api/v1/admin/jobs/{job_id}</code>（管理后台参考）。</p><div class="info custom-block"><p class="custom-block-title">别和 KiriVers 自己的发版搞混</p><p>这里的 CI Token 是<strong>你项目的流水线</strong>用来向 KiriVers 上传发布包的凭据。KiriVers 服务端自身的构建与发版是另一回事，见 <a href="/contribute/release">贡献 → 发版与 Docker</a>。</p></div><p>可浏览契约：<a href="/api/reference/">API 参考</a> 中的 <code>openapi.admin.json</code>（<a href="/api/scalar/admin" target="_blank" rel="noopener">新窗口打开 Scalar</a>）。</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};